    *returnSize = numsSize;
    int *res = (int*)malloc(sizeof(int)*numsSize);
    for(int i=0; i<numsSize; i++) res[i] = -1;

    int *stack = (int*)malloc(sizeof(int)*numsSize);
    int top = -1;

